var style="\n    .p-label {\n        display: flex;\n        align-items: center;\n        user-select: none;\n        gap: dt('label.gap');\n        font-size: dt('label.font.size');\n        font-weight: dt('label.font.weight');\n        color: dt('label.text.color');\n    }\n\n    .p-label:has(~ *:disabled),\n    [data-disabled] .p-label {\n        opacity: dt('label.disabled.opacity');\n        pointer-events: none;\n        cursor: not-allowed;\n    }\n";export{style};